import React, { useState } from 'react';
import { useNavigate, Link, useLocation } from 'react-router-dom'; 
import { useGoogleLogin } from '@react-oauth/google';
import { authAPI } from './api';


const MessagePopup = ({ isVisible, type, title, message, username, onClose }) => {
    if (!isVisible) return null;

    const getPopupStyle = () => {
        switch (type) {
            case 'success':
                return {
                    borderColor: '#10b981',
                    iconBg: '#10b981',
                    titleColor: '#10b981',
                    icon: '✓'
                };
            case 'error':
                return {
                    borderColor: '#ef4444',
                    iconBg: '#ef4444',
                    titleColor: '#ef4444',
                    icon: '✗'
                };
            case 'warning':
                return {
                    borderColor: '#f59e0b',
                    iconBg: '#f59e0b',
                    titleColor: '#f59e0b',
                    icon: '!'
                };
            default:
                return {
                    borderColor: '#6b7280',
                    iconBg: '#6b7280',
                    titleColor: '#6b7280',
                    icon: 'i'
                };
        }
    };

    const style = getPopupStyle();

    return (
        <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            zIndex: 1000
        }}>
            <div style={{
                backgroundColor: 'white',
                padding: '2rem',
                borderRadius: '12px',
                boxShadow: '0 10px 30px rgba(0,0,0,0.2)',
                textAlign: 'center',
                minWidth: '300px',
                maxWidth: '450px',
                border: `3px solid ${style.borderColor}`
            }}>
                <div style={{
                    width: '60px',
                    height: '60px',
                    backgroundColor: style.iconBg,
                    borderRadius: '50%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    margin: '0 auto 1rem',
                    fontSize: '30px',
                    color: 'white'
                }}>{style.icon}</div>
                <h3 style={{
                    color: style.titleColor,
                    marginBottom: '1rem',
                    fontSize: '1.5rem'
                }}>{title}</h3>
                {username && (
                    <p style={{
                        color: style.titleColor,
                        marginBottom: '1.5rem',
                        fontSize: '1.3rem',
                        fontWeight: '600',
                        textDecoration: 'none'
                    }}>Welcome {username}!</p>
                )}
                {message && (
                    <p style={{
                        color: '#6b7280',
                        marginBottom: '1.5rem',
                        lineHeight: '1.5'
                    }}>{message}</p>
                )}
                <button
                    onClick={onClose}
                    style={{
                        backgroundColor: style.iconBg,
                        color: 'white',
                        border: 'none',
                        padding: '0.75rem 2rem',
                        borderRadius: '8px',
                        fontSize: '1rem',
                        cursor: 'pointer',
                        transition: 'background-color 0.3s'
                    }}
                >OK</button>
            </div>
        </div>
    );
};

const Login = () => {
    const [gmail, setGmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [popup, setPopup] = useState({ isVisible: false, type: '', title: '', message: '' });
    const navigate = useNavigate();
    const location = useLocation();

    const showPopup = (type, title, message, username = '') => {
        setPopup({ isVisible: true, type, title, message, username });
    };

    const closePopup = () => {
        setPopup({ isVisible: false, type: '', title: '', message: '', username: '' });
    };

    const handleLogin = async (e) => {
        e.preventDefault();
        setError(''); 

        try {
            const response = await authAPI.login({
                gmail,
                password
            });

            if (response.data) {
                const userData = response.data;

                console.log('Login response userData:', userData);

                localStorage.setItem('userRole', userData.role);
                localStorage.setItem('tokenname', userData.username);
                localStorage.setItem('token', userData.jwt);

                // Handle profile picture URL - use fallback if not provided
                const profileUrl = userData.profilePictureUrl || userData.picture || null;
                if (profileUrl && profileUrl !== 'undefined' && profileUrl !== 'null') {
                    localStorage.setItem('profilePictureUrl', profileUrl);
                    console.log('Saved profile picture URL:', profileUrl);
                } else {
                    localStorage.removeItem('profilePictureUrl');
                    console.log('No valid profile picture URL in response, removed from storage');
                }

                window.dispatchEvent(new Event('localStorageUpdated')); 


                showPopup('success', 'Login Successful!', '', 'TestUser');


                setTimeout(() => {
                    closePopup();
                    if (location.state?.from) {
                        navigate(location.state.from);
                    } else {
                        navigate('/');
                    }
                }, 2000);
            } else {
                showPopup('error', 'Login Failed', 'Please check your credentials and try again.');
            }

        } catch (error) {
            showPopup('error', 'Connection Error', 'Could not connect to the server. Please check your internet connection and try again.');
        }
    };

     const handleGoogleLogin = useGoogleLogin({
    onSuccess: async (tokenResponse) => {
      try {
        const response = await fetch('http://localhost:8082/api/auth/google', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ token: tokenResponse.access_token })
        });

        if (response.ok) {
          const userData = await response.json();
          console.log('Google login response userData:', userData);

          localStorage.setItem('userRole', userData.role);
          localStorage.setItem('username', userData.username);
          localStorage.setItem('token', userData.jwt);

          // Handle profile picture URL - use fallback if not provided
          const profileUrl = userData.profilePictureUrl || userData.picture || null;
          if (profileUrl && profileUrl !== 'undefined' && profileUrl !== 'null') {
              localStorage.setItem('profilePictureUrl', profileUrl);
              console.log('Saved Google profile picture URL:', profileUrl);
          } else {
              localStorage.removeItem('profilePictureUrl');
              console.log('No valid profile picture URL in Google response, removed from storage');
          }

          window.dispatchEvent(new Event('localStorageUpdated')); 


          showPopup('success', 'Google Login Successful!', '', userData.username);


          setTimeout(() => {
            closePopup();
            if (location.state?.from) {
                navigate(location.state.from);
            } else {
                navigate('/');
            }
          }, 2000);
        } else {

          const errorText = await response.text();
          if (response.status === 404 || errorText.includes('not found') || errorText.includes('not registered')) {
            showPopup('warning', 'Registration Required', 'Sorry, you have to register first before using Google login. Please create an account with us.');
          } else {
            showPopup('error', 'Google Login Failed', 'Unable to sign in with Google. Please try again or use email login.');
          }
        }
      } catch (error) {
        showPopup('error', 'Google Login Error', 'An error occurred during Google login. Please try again.');
      }
    },
    onError: () => {
      showPopup('error', 'Google Login Failed', 'Google authentication was cancelled or failed. Please try again.');
    },
  });

    return (
        <>
            <MessagePopup 
                isVisible={popup.isVisible}
                type={popup.type}
                title={popup.title}
                message={popup.message}
                username={popup.username}
                onClose={closePopup}
            />
            <div style={{ maxWidth: '450px', margin: '5rem auto', padding: '2rem', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', borderRadius: '12px' }}>
            <h2 style={{ textAlign: 'center', marginBottom: '1.5rem' }}>Login</h2>
            <form onSubmit={handleLogin}>
                <div style={{ marginBottom: '1rem' }}>
                    <label>Email</label>
                    <input
                        type="email"
                        className="search-input" 
                        style={{ width: '100%', padding: '0.75rem', marginTop: '0.25rem', background: '#f3f4f6' }}
                        placeholder="your.email@example.com"
                        value={gmail}
                        onChange={(e) => setGmail(e.target.value)}
                        required
                    />
                </div>
                <div style={{ marginBottom: '1.5rem' }}>
                    <label>Password</label>
                    <input
                        type="password"
                        className="search-input"
                        style={{ width: '100%', padding: '0.75rem', marginTop: '0.25rem', background: '#f3f4f6' }}
                        placeholder="Password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                    />
                </div>
                {error && <p style={{ color: '#ef4444', textAlign: 'center', marginBottom: '1rem' }}>{error}</p>}
                <button type="submit" className="btn-primary" style={{ width: '100%', border: 'none' }}>
                    Login
                </button>
                <button onClick={() => handleGoogleLogin()} className="btn-secondary" style={{ width: '100%', border: 'none', marginTop: '1rem' }}>
                    Sign in with Google
                </button>
                <p style={{ textAlign: 'center', marginTop: '1rem' }}>
                    Don't have an account? <Link to="/register" style={{ color: '#10b981' }}>Register here</Link>
                </p>
            </form>
            </div>
        </>
    );
}

export default Login;
